      return
    }

    submitInFlight.current = true
    setBusy(true)
    setError(null)
    if (decision?.kind === 'setup') setSetup(decision.choice)
    if (decision?.kind === 'issue') setIssueCommand(decision.choice)
    const setupApprovalHash = setupChoice === 'run'
